use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn transform_directory (dir : & str , output : & str , mock : bool , safety : & str , dao : bool) -> Result < () > { println ! ("🛡️ Transforming directory with syscall interception...") ; println ! ("   Source: {}" , dir) ; println ! ("   Output: {}" , output) ; println ! ("   Mock mode: {}" , mock) ; println ! ("   Safety level: {}" , safety) ; println ! ("   DAO governance: {}" , dao) ; let safety_level = match safety { "permissive" => TypeSafetyLevel :: Permissive , "strict" => TypeSafetyLevel :: Strict , "paranoid" => TypeSafetyLevel :: Paranoid , _ => TypeSafetyLevel :: Strict , } ; let mut interceptor = create_default_syscall_interceptor () ; interceptor . mock_mode = mock ; interceptor . dao_governance = dao ; interceptor . type_safety_level = safety_level ; let mut transformer = SyscallAstTransformer :: new (interceptor) ; std :: fs :: create_dir_all (output) ? ; let mut transformed_count = 0 ; for entry in walkdir :: WalkDir :: new (dir) { let entry = entry ? ; if entry . file_type () . is_file () && entry . path () . extension () . map_or (false , | ext | ext == "rs") { match transformer . transform_file (entry . path ()) { Ok (transformed_code) => { let relative_path = entry . path () . strip_prefix (dir) ? ; let output_path = Path :: new (output) . join (relative_path) ; if let Some (parent) = output_path . parent () { std :: fs :: create_dir_all (parent) ? ; } std :: fs :: write (& output_path , transformed_code) ? ; transformed_count += 1 ; if transformed_count % 100 == 0 { println ! ("   Transformed {} files..." , transformed_count) ; } } Err (e) => { eprintln ! ("⚠️ Failed to transform {:?}: {}" , entry . path () , e) ; } } } } println ! ("✅ Transformation completed!") ; println ! ("   Files transformed: {}" , transformed_count) ; Ok (()) }